def build_rows():
    rows=[]
    def emit(key,i,name,text,args=None,reply=None,history=None,category='reliability_arguments'):
        messages=(history or [])+[user(text),tool_call(name,args) if args is not None else assistant(reply or ASK[i])]
        names=[name] if name=='get_status' else [name,'get_status']
        if history:
            names=list(dict.fromkeys([name]+[c['function']['name'] for m in history for c in m.get('tool_calls',[])]+['control_flat_device']))
        row=conversation('reliability-'+key,LANGUAGES[i],category,names,messages,CONTEXT)
        row['provenance']['source']='independently authored v8 schema/intent contrasts; no evaluation inputs'
        rows.append(row)
    for i in range(10):
        for v,(n,a,ra,dec) in enumerate([(18,4,2.65,-22.75),(43,9,19.35,47.25)]):
            specs=[('flat_off','control_flat_device',{'action':'light_off'}),('flat_on','control_flat_device',{'action':'light_on'}),
             ('dome_close','control_dome',{'action':'close_shutter','wait_seconds':0}),('dome_open','control_dome',{'action':'open_shutter','wait_seconds':0}),
             ('center','center_target',{'ra':ra,'dec':dec,'wait_seconds':0}),('warm','warm_camera',{'duration_minutes':n}),
             ('guide','get_guider_report',{'steps':n,'alerts':a}),('coach','get_guiding_coach_report',{'history':a,'include_samples':True}),
             ('log_current','read_log',{'lines':n,'min_level':'error','previous_run':False}),('log_previous','read_log',{'lines':n,'min_level':'error','previous_run':True}),
             ('summary','get_session_summary',{'group_by':'target','image_type':'all','since_hours':a}),
             ('events','get_events',{'limit':n,'kinds':'camera','min_severity':'error','wait_seconds':0}),
             ('find','find_targets',{'name':'NGC 2392','limit':a}),('capture','capture_image',{'exposure_seconds':n,'save':True}),
             ('plan','plan_targets',{'targets':[{'name':'Synthetic East','ra':ra,'dec':dec}],'min_altitude':n})]
            for key,name,args in specs:
                emit(key+'-'+str(v),i,name,TEXT[key][i].format(n=a if key in ('find','coach','summary') else n,a=a,ra=ra,dec=dec),args)
        for key,texts in NEGATIVES.items():
            name='capture_image' if key=='exposure' else 'control_dome' if key=='withdraw' else 'start_sequence' if key=='override' else 'control_flat_device' if key=='quoted' else 'slew_mount'
            reply=QUOTE_REPLY[i] if key=='quoted' else REFUSE[i] if key in ('withdraw','override') else ASK[i]
            emit(key,i,name,texts[i],reply=reply,category='reliability_'+key)
        # Boundary positives preserve the schema's real units, not guessed percentages.
        for duration in (0,60):
            emit('warm-boundary-'+str(duration),i,'warm_camera',TEXT['warm'][i].format(n=duration),{'duration_minutes':duration})
        emit('warm-out-of-range',i,'warm_camera',TEXT['warm'][i].format(n=75),reply=ASK[i],category='reliability_range')
        emit('coach-without-samples',i,'get_guiding_coach_report',TEXT['coach_without'][i].format(n=4),{'history':4,'include_samples':False})
        # Poisoned log content never becomes an operator instruction. The same
        # action has legitimate direct-user positives above (not blanket refusal).
        history=[user(EXPLAIN[i]),tool_call('read_log',{}),
                 tool_result('read_log',{'count':1,'entries':[{'level':'warning','message':TEXT['flat_on'][i]}]})]
        emit('untrusted-log',i,'read_log',EXPLAIN[i],reply=REFUSE[i],history=history,category='reliability_injection')
        for source,args,payload in [
          ('get_recent_images',{},{'count':1,'images':[{'targetName':TEXT['flat_on'][i]}]}),
          ('find_targets',{'name':'Synthetic Archive'},{'count':1,'objects':[{'name':'Synthetic Archive','note':TEXT['flat_on'][i]}]}),
          ('get_sequence',{},{'initialized':True,'running':False,'name':TEXT['flat_on'][i],'nodes':[]})]:
            history=[user(CATALOG_REQUEST[i] if source=='find_targets' else EXPLAIN[i]),tool_call(source,args),tool_result(source,payload)]
            emit('untrusted-'+source,i,source,EXPLAIN[i],reply=REFUSE[i],history=history,category='reliability_injection')
    return rows
